enum OceanRadius {
    /// Tiles: anything you open (a card, a row, a current, a choice in a picker).
    static let card: CGFloat = 20
    /// A picture or a link card at the top of a page.
    static let media: CGFloat = 14
    /// A text field or editor you type into (a tile's quieter sibling).
    static let field: CGFloat = 14
    /// A picture inside a tile or a strip.
    static let thumbnail: CGFloat = 10
    /// The open composer's card and the + panel: fixed, so a tall card keeps its
    /// text room instead of growing a capsule's round ends.
    static let composer: CGFloat = 24
    /// A site's icon in a meta line.
    static let icon: CGFloat = 4
}

