// MARK: - Material: shadow

/// One soft drop shadow lifts a surface just above the water. The shadow
/// belongs to the shape alone, so it stays cheap even under a picture.
enum OceanShadow {
    /// Under a tile, a field, a link card.
    static let tile = OceanShadowValue(color: Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 0.28), radius: 14, x: 0, y: 8)
    /// Under a raised control: tighter, since it sits closer to the page.
    static let control = OceanShadowValue(color: Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 0.28), radius: 8, x: 0, y: 4)
    /// Under a thumb inside a control: the segmented switch's selected part.
    static let inset = OceanShadowValue(color: Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 0.22), radius: 4, x: 0, y: 2)
    /// Under a floating bar before iOS 26 (Liquid Glass draws its own).
    static let bar = OceanShadowValue(color: Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 0.35), radius: 16, x: 0, y: 6)
    /// Behind words laid straight on the water, so they read over anything beneath.
    static let text = OceanShadowValue(color: Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 0.5), radius: 8, x: 0, y: 0)
}

// MARK: - Motion

/// Facet three: how things change. Motion is atmosphere, never information;
/// every fact it implies is reachable through a tap, a label, or the Library.
/// Five motions cover every state change; the lamp's slow choreography on Tide,
/// the microphone's level bars and the sinking words of a caught whisper are
/// art-directed and stay in their views.
enum OceanMotion {
    /// A control answering a finger: a press, a glyph swap, a tint change on the
    /// disc.
    static let touch = Animation.easeOut(duration: 0.15)
    /// A quick state change: a filter on or off, a bar showing or hiding, the
    /// Reduce Motion stand-in for anything slower.
    static let quick = Animation.easeOut(duration: 0.18)
    /// The standard settle: layout, folding, a section opening, a scroll to the
    /// top.
    static let standard = Animation.smooth(duration: 0.35)
    /// Something floating in or out over the page: a toast, the capture overlay's
    /// phases, a reorder, a page turn.
    static let lift = Animation.spring(response: 0.36, dampingFraction: 0.86)
    /// The gentle arrival of something new: a thought rising on Tide, a hint
    /// breathing in and out.
    static let gentle = Animation.timingCurve(0.3, 0, 0.2, 1, duration: 0.8)
}
